begin;
create table public.cash_registers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),user_id uuid not null,opened_at timestamptz not null default now(),closed_at timestamptz,initial_cash numeric(12,2) not null check(initial_cash>=0),expected_cash numeric(12,2),actual_cash numeric(12,2),difference numeric(12,2),status text not null default 'aberto' check(status in('aberto','fechado')),total_sales_cash numeric(12,2) not null default 0,total_sales_pix numeric(12,2) not null default 0,total_sales_card numeric(12,2) not null default 0,total_supplements numeric(12,2) not null default 0,total_withdrawals numeric(12,2) not null default 0,unique(id,company_id),constraint cash_user_company_fkey foreign key(user_id,company_id) references public.profiles(id,company_id));
create unique index cash_one_open_company_idx on public.cash_registers(company_id) where status='aberto';
create index cash_company_date_idx on public.cash_registers(company_id,opened_at desc);
create index cash_user_company_idx on public.cash_registers(user_id,company_id);
create table public.cash_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),cash_register_id uuid not null,movement_type text not null check(movement_type in('sangria','suprimento')),amount numeric(12,2) not null check(amount>0),description text not null,created_by uuid not null,created_at timestamptz not null default now(),constraint movement_cash_company_fkey foreign key(cash_register_id,company_id) references public.cash_registers(id,company_id),constraint movement_user_company_fkey foreign key(created_by,company_id) references public.profiles(id,company_id));
create index cash_movements_register_company_idx on public.cash_movements(cash_register_id,company_id);
create index cash_movements_user_company_idx on public.cash_movements(created_by,company_id);
alter table public.cash_registers enable row level security; alter table public.cash_movements enable row level security;
create policy cash_select on public.cash_registers for select to authenticated using(private.is_company_member(company_id));
create policy cash_insert on public.cash_registers for insert to authenticated with check(private.has_company_role(company_id,array['proprietario','administrador','gerente','caixa']));
create policy cash_update on public.cash_registers for update to authenticated using(private.has_company_role(company_id,array['proprietario','administrador','gerente','caixa'])) with check(private.has_company_role(company_id,array['proprietario','administrador','gerente','caixa']));
create policy cash_movements_select on public.cash_movements for select to authenticated using(private.is_company_member(company_id));
create policy cash_movements_insert on public.cash_movements for insert to authenticated with check(private.has_company_role(company_id,array['proprietario','administrador','gerente','caixa']));
grant select,insert,update on public.cash_registers to authenticated; grant select,insert on public.cash_movements to authenticated; revoke all on public.cash_registers,public.cash_movements from anon;

create function public.open_cash_register(p_initial_cash numeric) returns public.cash_registers language plpgsql security invoker set search_path='' as $$ declare v_company uuid;v_cash public.cash_registers; begin select company_id into v_company from public.profiles where id=(select auth.uid()) and is_active and role=any(array['proprietario','administrador','gerente','caixa']); if v_company is null or p_initial_cash<0 then raise exception 'Abertura inválida'; end if; insert into public.cash_registers(company_id,user_id,initial_cash) values(v_company,(select auth.uid()),p_initial_cash) returning * into v_cash; return v_cash; end;$$;
create function public.register_cash_movement(p_type text,p_amount numeric,p_description text) returns uuid language plpgsql security invoker set search_path='' as $$ declare v_company uuid;v_cash uuid;v_id uuid; begin select company_id into v_company from public.profiles where id=(select auth.uid()) and is_active and role=any(array['proprietario','administrador','gerente','caixa']); select id into v_cash from public.cash_registers where company_id=v_company and status='aberto' for update; if v_cash is null or p_type not in('sangria','suprimento') or p_amount<=0 then raise exception 'Movimento inválido ou caixa fechado'; end if; insert into public.cash_movements(company_id,cash_register_id,movement_type,amount,description,created_by) values(v_company,v_cash,p_type,p_amount,p_description,(select auth.uid())) returning id into v_id; update public.cash_registers set total_supplements=total_supplements+case when p_type='suprimento' then p_amount else 0 end,total_withdrawals=total_withdrawals+case when p_type='sangria' then p_amount else 0 end where id=v_cash; return v_id; end;$$;
create function public.close_cash_register(p_actual_cash numeric) returns public.cash_registers language plpgsql security invoker set search_path='' as $$ declare v_company uuid;v_cash public.cash_registers;v_money numeric;v_pix numeric;v_card numeric;v_expected numeric; begin select company_id into v_company from public.profiles where id=(select auth.uid()) and is_active and role=any(array['proprietario','administrador','gerente','caixa']); select * into v_cash from public.cash_registers where company_id=v_company and status='aberto' for update; if not found or p_actual_cash<0 then raise exception 'Fechamento inválido'; end if; select coalesce(sum(amount) filter(where payment_method='dinheiro'),0),coalesce(sum(amount) filter(where payment_method='pix'),0),coalesce(sum(amount) filter(where payment_method in('cartao_debito','cartao_credito')),0) into v_money,v_pix,v_card from public.service_order_payments where company_id=v_company and paid_at>=v_cash.opened_at; select v_money+coalesce(sum(total_amount) filter(where payment_method='dinheiro'),0),v_pix+coalesce(sum(total_amount) filter(where payment_method='pix'),0),v_card+coalesce(sum(total_amount) filter(where payment_method in('cartao_debito','cartao_credito')),0) into v_money,v_pix,v_card from public.sales where company_id=v_company and status='concluida' and created_at>=v_cash.opened_at; v_expected:=v_cash.initial_cash+v_money+v_cash.total_supplements-v_cash.total_withdrawals; update public.cash_registers set closed_at=now(),expected_cash=v_expected,actual_cash=p_actual_cash,difference=p_actual_cash-v_expected,status='fechado',total_sales_cash=v_money,total_sales_pix=v_pix,total_sales_card=v_card where id=v_cash.id returning * into v_cash; return v_cash; end;$$;
revoke all on function public.open_cash_register(numeric),public.register_cash_movement(text,numeric,text),public.close_cash_register(numeric) from public,anon; grant execute on function public.open_cash_register(numeric),public.register_cash_movement(text,numeric,text),public.close_cash_register(numeric) to authenticated;
commit;
